import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"45、【萃】 坤下兑上","description":"横渠易说 - 45、【萃】 坤下兑上","frontmatter":{"title":"45、【萃】 坤下兑上","description":"横渠易说 - 45、【萃】 坤下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/047.md","filePath":"zh/classics/hengqu/047.md"}'),l={name:"zh/classics/hengqu/047.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_45、【萃】-坤下兑上" tabindex="-1">45、【萃】 坤下兑上 <a class="header-anchor" href="#_45、【萃】-坤下兑上" aria-label="Permalink to “45、【萃】 坤下兑上”">​</a></h1><p>姤者遇也，物相遇而后聚，故受之以萃。 与涣卦义同，故繇辞互见。 萃而不见大人之德，吝道也。</p><h3 id="彖曰-萃-聚也-顺以说-刚中而应-故聚也。-王假有庙-致孝享也。-利见大人亨-聚以正也。-用大牲吉-利有攸往-顺天命也。观其所聚而天地万物之情可见矣。" tabindex="-1">彖曰：萃，聚也，顺以说，刚中而应，故聚也。“王假有庙”，致孝享也。“利见大人亨”，聚以正也。“用大牲吉，利有攸往”，顺天命也。观其所聚而天地万物之情可见矣。 <a class="header-anchor" href="#彖曰-萃-聚也-顺以说-刚中而应-故聚也。-王假有庙-致孝享也。-利见大人亨-聚以正也。-用大牲吉-利有攸往-顺天命也。观其所聚而天地万物之情可见矣。" aria-label="Permalink to “彖曰：萃，聚也，顺以说，刚中而应，故聚也。“王假有庙”，致孝享也。“利见大人亨”，聚以正也。“用大牲吉，利有攸往”，顺天命也。观其所聚而天地万物之情可见矣。”">​</a></h3><h3 id="象曰-泽上于地-萃-君子以除戎器-戒不虞。" tabindex="-1">象曰：泽上于地，萃，君子以除戎器，戒不虞。 <a class="header-anchor" href="#象曰-泽上于地-萃-君子以除戎器-戒不虞。" aria-label="Permalink to “象曰：泽上于地，萃，君子以除戎器，戒不虞。”">​</a></h3><p>聚而致享，必有庙乃尽其实。 聚而不见大人之德，吝道也。 聚不以正，私邪胜也。 富聚之世，顺天之命，用大牲有所进为宜。 散而通之，顺天命而不凝于物也。凝一作疑。</p><h3 id="初六-有孚不终-乃乱乃萃。若号一握-为笑勿恤-往无咎。-象曰-乃乱乃萃-其志乱也。" tabindex="-1">初六，有孚不终，乃乱乃萃。若号一握，为笑勿恤，往无咎。 象曰：“乃乱乃萃”，其志乱也。 <a class="header-anchor" href="#初六-有孚不终-乃乱乃萃。若号一握-为笑勿恤-往无咎。-象曰-乃乱乃萃-其志乱也。" aria-label="Permalink to “初六，有孚不终，乃乱乃萃。若号一握，为笑勿恤，往无咎。 象曰：“乃乱乃萃”，其志乱也。”">​</a></h3><p>萃聚之世，物各以近相求，所处远者，虽有其应，不能专一。初六履不以中，萃而志乱，故为众轻侮，若能啼号齐咨，专一其守，不恤众侮，则往而无咎。</p><h3 id="六二-引吉-无咎。孚乃利用禴。-象曰-引吉无咎-中未变也。" tabindex="-1">六二，引吉，无咎。孚乃利用禴。 象曰：“引吉无咎”，中未变也。 <a class="header-anchor" href="#六二-引吉-无咎。孚乃利用禴。-象曰-引吉无咎-中未变也。" aria-label="Permalink to “六二，引吉，无咎。孚乃利用禴。 象曰：“引吉无咎”，中未变也。”">​</a></h3><p>物思其聚之时，能自持不变，引而后往，吉乃无咎。凡言“利用禴”，皆诚素着白于幽明之际，未孚而略礼，则神怒而民怨。</p><h3 id="六三-萃如嗟如-无攸利。往无咎-小吝。-象曰-往无咎-上巽也。" tabindex="-1">六三，萃如嗟如，无攸利。往无咎，小吝。 象曰：“往无咎”，上巽也。 <a class="header-anchor" href="#六三-萃如嗟如-无攸利。往无咎-小吝。-象曰-往无咎-上巽也。" aria-label="Permalink to “六三，萃如嗟如，无攸利。往无咎，小吝。 象曰：“往无咎”，上巽也。”">​</a></h3><h3 id="九四-大吉-无咎-象曰-大吉无咎-位不当也。" tabindex="-1">九四，大吉，无咎， 象曰：“大吉无咎”，位不当也。 <a class="header-anchor" href="#九四-大吉-无咎-象曰-大吉无咎-位不当也。" aria-label="Permalink to “九四，大吉，无咎， 象曰：“大吉无咎”，位不当也。”">​</a></h3><p>位非极显而有物之萃，非大吉则悔吝必矣。</p><h3 id="九五-萃有位-无咎。匪孚-元永贞-悔亡。-象曰-萃有位-志未光也。" tabindex="-1">九五，萃有位，无咎。匪孚，元永贞，悔亡。 象曰：“萃有位”，志未光也。 <a class="header-anchor" href="#九五-萃有位-无咎。匪孚-元永贞-悔亡。-象曰-萃有位-志未光也。" aria-label="Permalink to “九五，萃有位，无咎。匪孚，元永贞，悔亡。 象曰：“萃有位”，志未光也。”">​</a></h3><p>居得盛位不能见，以大人之德系应于二，故曰“有位”，履非不正，故无咎。然非君人之大信，为德非厚，不能无悔，故元永贞而后悔亡。</p><h3 id="上六-齐咨涕洟-无咎。-象曰-齐咨涕洟-未安上也。" tabindex="-1">上六，齐咨涕洟，无咎。 象曰：“齐咨涕洟”，未安上也。 <a class="header-anchor" href="#上六-齐咨涕洟-无咎。-象曰-齐咨涕洟-未安上也。" aria-label="Permalink to “上六，齐咨涕洟，无咎。 象曰：“齐咨涕洟”，未安上也。”">​</a></h3><p>以阴居上，极物之萃，非所堪也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
